3	import java.util.Locale;
4	
5	/**
6	 * American Soundex of a name: the first letter followed by three digits encoding the remaining
7	 * consonants (vowels drop out, letters sharing a code collapse, {@code h}/{@code w} are transparent).
8	 * Two surnames that sound alike share a code, which is how the identity key and the soft-match rule
9	 * group households phonetically rather than on exact spelling.
10	 */
11	public final class Soundex {
12	
13	    private Soundex() {
14	    }
15	
16	    public static String of(String value) {
17	        String letters = value == null ? "" : value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
18	        if (letters.isEmpty()) {
19	            return "";
20	        }
21	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
22	        char prev = digit(letters.charAt(0));
23	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
24	            char c = letters.charAt(i);
25	            char d = digit(c);
26	            if (d != '0' && d != prev) {
27	                code.append(d);
28	            }
29	            if (c != 'H' && c != 'W') {
30	                prev = d;
31	            }
32	        }
33	        while (code.length() < 4) {
34	            code.append('0');
35	        }
36	        return code.toString();
37	    }
38	
39	    private static char digit(char c) {
40	        switch (c) {
41	            case 'B': case 'F': case 'P': case 'V': return '1';
42	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z': return '2';
43	            case 'D': case 'T': return '3';
44	            case 'L': return '4';
45	            case 'M': case 'N': return '5';
46	            case 'R': return '6';
47	            default: return '0';
48	        }
49	    }
50	}
