3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Locality;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Assigns the owner's unified {@code memberId} as {@code <REGION><FY><HASH8><CHK>}: REGION is
13	 * the region code for the owner (postcode-derived, city as fallback), FY the 2-digit fiscal
14	 * year of registration, HASH8 the first eight upper-case hex characters of SHA-256 over
15	 * (normalized telephone + last name) and CHK a single Luhn check digit over the preceding
16	 * digits. No sequence number is used, so the identity is stable and city-count independent.
17	 */
18	public class AssignCustomerCode {
19	
20	    public void service(@Val Owner owner) {
21	        String region = Locality.of(owner.getCity(), owner.getPostcode());
22	        String fy = String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100);
23	        String base = region + fy + hash8(owner.getTelephone() + owner.getLastName());
24	        owner.setCustomerCode(base + CheckDigit.of(base));
25	    }
26	
27	    private static String hash8(String value) {
28	        try {
29	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
30	            StringBuilder hex = new StringBuilder();
31	            for (int i = 0; hex.length() < 8; i++) {
32	                hex.append(String.format("%02X", digest[i]));
33	            }
34	            return hex.substring(0, 8);
35	        }
36	        catch (NoSuchAlgorithmException e) {
37	            throw new IllegalStateException(e);
38	        }
39	    }
40	}
