1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Consolidated duplicate check: the former telephone, email and household checks are now a single
11	 * equality on the identity key ({@link IdentityKey}). Two owners are duplicates only when their
12	 * telephone and email both match, so members of the same household with different telephones have
13	 * different keys and are both allowed. Rejects a collision with a 409 via
14	 * {@link DuplicateIdentityException}.
15	 */
16	public class EnsureUniqueIdentity {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateIdentityException {
20	        String key = IdentityKey.of(request.getTelephone(), request.getEmail(), request.getLastName());
21	        for (Owner owner : ownerRepository.findAll()) {
22	            if (!owner.isDeleted() && key.equals(IdentityKey.of(owner))) {
23	                throw new DuplicateIdentityException(key);
24	            }
25	        }
26	    }
27	}
