22	        String householdId = HouseholdId.of(request.getLastName(), request.getPostcode());
23	        for (Owner owner : ownerRepository.findAll()) {
24	            if (!owner.isDeleted() && householdId.equals(owner.getHouseholdId())) {
25	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
