1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Collection;
4	import java.util.Objects;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Level ceiling for an owner: their {@link MembershipLevel} may not exceed one above the current
11	 * maximum level among the OTHER members of their household (same {@code householdId}). With no
12	 * other household member the ceiling does not apply. Mirrors the household-factor weighting used
13	 * by {@link Membership} so a member's level is measured on the same scale.
14	 */
15	public final class HouseholdCeiling {
16	
17	    private static final int HOUSEHOLD_POINTS = 2;
18	
19	    private static final int HOUSEHOLD_THRESHOLD = 3;
20	
21	    private HouseholdCeiling() {
22	    }
23	
24	    public static int cap(Owner owner, int level, OwnerRepository ownerRepository) {
25	        String householdId = owner.getHouseholdId();
26	        Collection<Owner> all = ownerRepository.findAll();
27	        long size = all.stream().filter(other -> Objects.equals(householdId, other.getHouseholdId())).count();
28	        int householdPoints = size >= HOUSEHOLD_THRESHOLD ? HOUSEHOLD_POINTS : 0;
29	        int max = -1;
30	        for (Owner other : all) {
31	            if (!Objects.equals(other.getId(), owner.getId())
32	                    && Objects.equals(householdId, other.getHouseholdId())) {
33	                max = Math.max(max, MembershipLevel.of(MembershipPoints.of(other) + householdPoints));
34	            }
35	        }
36	        return max < 0 ? level : Math.min(level, max + 1);
37	    }
38	}
