3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Aggregate the membership points an owner earns from entity-derivable factors
7	 * ({@link EmailFactor}, {@link NamesakeFactor}, {@link TenureFactor}). The household
8	 * factor needs the repository to count members, so it is added at response time by
9	 * {@link Membership}; this sum feeds the level-mapping in {@link MembershipLevel}.
10	 */
11	public final class MembershipPoints {
12	
13	    private static final int BASE = 0;
14	
15	    private MembershipPoints() {
16	    }
17	
18	    public static int of(Owner owner) {
19	        return BASE + EmailFactor.points(owner) + NamesakeFactor.points(owner) + TenureFactor.points(owner);
20	    }
21	}
